from garagedesk.vehicles.store import Fleet
from garagedesk.vehicles.models import Vehicle
def mk(n, cat='x'):
    s = Fleet()
    for k in range(n):
        s.add(Vehicle(id='k%02d' % k, model='N%02d' % k, kind=cat, units=(k * 5) % 7, price=1.0 + k))
    return s
from garagedesk.vehicles.errors import Invalid
s = mk(2)
try:
    s.add(Vehicle(id='k01', model='z', kind='c'))
except Invalid as e:
    print(e, s.count(), s.get('k01').model)

